#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int compare_asc(const void *a, const void *b) {
    long long val = *(const long long*)a;
    long long other = *(const long long*)b;
    if (val < other) return -1;
    if (val > other) return 1;
    return 0;
}

long long* sortEvenOdd(const long long* arr, size_t len, size_t* result_len) {
    if (len == 0) {
        *result_len = 0;
        return NULL;
    }

    long long* evens = malloc(len * sizeof(long long));
    long long* odds = malloc(len * sizeof(long long));
    size_t even_count = 0;
    size_t odd_count = 0;

    for (size_t i = 0; i < len; i++) {
        long long val = arr[i];
        if (val % 2 == 0) {
            evens[even_count++] = val;
        } else {
            odds[odd_count++] = val;
        }
    }

    qsort(evens, even_count, sizeof(long long), compare_asc);
    qsort(odds, odd_count, sizeof(long long), compare_asc);

    long long* result = malloc(len * sizeof(long long));
    size_t result_idx = 0;
    size_t even_idx = 0;
    size_t odd_idx = 0;

    while (even_idx < even_count && odd_idx < odd_count) {
        result[result_idx++] = evens[even_idx++];
        result[result_idx++] = odds[odd_idx++];
    }

    while (even_idx < even_count) {
        result[result_idx++] = evens[even_idx++];
    }

    while (odd_idx < odd_count) {
        result[result_idx++] = odds[odd_idx++];
    }

    free(evens);
    free(odds);

    *result_len = len;
    return result;
}

void print_array(const long long* arr, size_t len) {
    printf("[");
    for (size_t i = 0; i < len; i++) {
        printf("%lld", arr[i]);
        if (i < len - 1) printf(", ");
    }
    printf("]");
}

int main() {
    struct {
        long long* arr;
        size_t len;
    } test_cases[] = {
        {(long long[]){3, 1, 4, 1, 5, 9, 2, 6}, 8},
        {(long long[]){}, 0},
        {(long long[]){0, 0, 0}, 3},
        {(long long[]){1, 3, 5, 7, 9}, 5},
        {(long long[]){2, 4, 6, 8, 10}, 5},
        {(long long[]){-5, -4, -3, -2, -1, 0, 1, 2, 3, 4}, 10},
        {(long long[]){42}, 1},
        {(long long[]){7, 7, 7, 7}, 4}
    };

    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_tests; i++) {
        printf("Test %d - Input: ", i + 1);
        print_array(test_cases[i].arr, test_cases[i].len);
        printf("\n");

        size_t result_len;
        long long* result = sortEvenOdd(test_cases[i].arr, test_cases[i].len, &result_len);

        printf("        Output: ");
        print_array(result, result_len);
        printf("\n\n");

        free(result);
    }

    return 0;
}

