import java.util.*;

public class Solution {
    public static int[] sortEvenOdd(int[] arr) {
        if (arr.length == 0) {
            return new int[0];
        }

        List<Integer> evens = new ArrayList<>();
        List<Integer> odds = new ArrayList<>();

        for (int val : arr) {
            if (val % 2 == 0) {
                evens.add(val);
            } else {
                odds.add(val);
            }
        }

        Collections.sort(evens);
        Collections.sort(odds);

        int[] result = new int[arr.length];
        int evenIdx = 0;
        int oddIdx = 0;

        for (int i = 0; i < result.length; i++) {
            if (evenIdx < evens.size()) {
                result[i] = evens.get(evenIdx);
                evenIdx++;
            } else {
                result[i] = odds.get(oddIdx);
                oddIdx++;
            }
        }

        return result;
    }

    public static void main(String[] args) {
        // Test case 1: Normal case with mixed numbers
        int[] arr1 = {5, 2, 8, 1, 9, 4, 6, 3, 7};
        System.out.println(Arrays.toString(sortEvenOdd(arr1)));

        // Test case 2: Empty array
        int[] arr2 = {};
        System.out.println(Arrays.toString(sortEvenOdd(arr2)));

        // Test case 3: All even numbers
        int[] arr3 = {8, 4, 6, 2, 10};
        System.out.println(Arrays.toString(sortEvenOdd(arr3)));

        // Test case 4: All odd numbers
        int[] arr4 = {7, 3, 9, 1, 5};
        System.out.println(Arrays.toString(sortEvenOdd(arr4)));

        // Test case 5: Contains zeros and negative numbers
        int[] arr5 = {0, -3, 2, -1, 4, -2, 1};
        System.out.println(Arrays.toString(sortEvenOdd(arr5)));

        // Test case 6: Single element
        int[] arr6 = {42};
        System.out.println(Arrays.toString(sortEvenOdd(arr6)));

        // Test case 7: All equal numbers (even)
        int[] arr7 = {2, 2, 2, 2};
        System.out.println(Arrays.toString(sortEvenOdd(arr7)));

        // Test case 8: All equal numbers (odd)
        int[] arr8 = {3, 3, 3, 3};
        System.out.println(Arrays.toString(sortEvenOdd(arr8)));
    }
}
